<?php require __DIR__.'/config.php';$pdo=db();$code=trim($_GET['code']??$_POST['code']??'');$order=null;$items=[];if($code!==''){$s=$pdo->prepare("SELECT * FROM orders WHERE order_code=?");$s->execute([$code]);$order=$s->fetch();if($order){$s=$pdo->prepare("SELECT * FROM order_items WHERE order_id=?");$s->execute([$order['id']]);$items=$s->fetchAll();}}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Track Order — Aastha</title><link rel="stylesheet" href="assets/css/store.css"></head><body><header class="simple-head wrap"><a class="brand" href="index.php"><span class="brand-mark">A</span><span>Aastha<small>FRESH EVERY DAY</small></span></a><a href="index.php">Home</a></header><main class="wrap page-main"><span class="eyebrow">ORDER UPDATES</span><h1>Track your order</h1><form class="track-form" method="post"><label>Order number<input name="code" required placeholder="e.g. AS261028ABC123" value="<?=e($code)?>"></label><button class="green-btn">Track order →</button></form><?php if($code!==''&&!$order): ?><div class="notice error">We couldn't find that order number. Please check it and try again.</div><?php endif; if($order): ?><div class="tracking-card"><div class="tracking-head"><div><small>ORDER NUMBER</small><h2><?=e($order['order_code'])?></h2></div><span class="status status-<?=strtolower(str_replace(' ','-',$order['status']))?>"><?=e($order['status'])?></span></div><div class="tracking-steps"><?php $steps=['Pending','Confirmed','Processing','Out for Delivery','Delivered'];$pos=array_search($order['status'],$steps);foreach($steps as $i=>$step): ?><div class="track-step <?=($pos!==false&&$i<=$pos?'done':'')?>"><span><?=($pos!==false&&$i<=$pos?'✓':($i+1))?></span><b><?=e($step)?></b></div><?php endforeach; ?></div><h3>Items</h3><?php foreach($items as $item): ?><p><?=e($item['product_name'])?> × <?=(int)$item['quantity']?> <b class="float-right"><?=money((float)$item['price']*(int)$item['quantity'])?></b></p><?php endforeach; ?><hr><p>Delivery address: <?=e($order['address'])?></p><div class="summary-total"><span>Total (COD)</span><b><?=money((float)$order['total'])?></b></div></div><?php endif; ?></main></body></html>